// Feature catalogue for /tinh-nang/ and /en/features/.
// Source of truth (read 25/10/2026): agentos-local/docs/HUONG_DAN_SU_DUNG.md (user guide, checked against the real UI),
// GD6..GD9_PLAN.md, BAO_CAO_TU_DONG.md, TONG_KET_GD6-9.md, CHO_ANH.md; GĐ0–5 chat features from src/data/content.ts.
// Status rule: "stable" = done + automated tests + tried in the real UI (fake or real model);
// "beta" = only tested against simulated external services, or unofficial. Flags: setup = needs the customer's own
// account/bot/domain; review = security/legal expert review advised before customer hand-over (CHO_ANH.md ⚠️ list).
// img keys: file names (no extension) in src/assets/f/*.webp or src/assets/shots/*.png; imgEn = English-UI variant.
export type Status = "stable" | "beta";
type Text = { t: string; what: string; when: string; where: string };
// since: the upgrade phase (GĐ10–13, Oct 2026) that added or substantially upgraded the feature; shown as a "New" chip.
// GĐ10–13 sources (read 27/10/2026): agentos-local/docs/BAO_CAO_GD10..13.md, GD13_PARITY.md. Phases are on `dev`, not yet on the demo server.
export interface Feature { id: string; s: Status; setup?: boolean; review?: boolean; since?: 10 | 11 | 12 | 13; img?: string; imgEn?: string; vi: Text; en: Text }
export interface Area { id: string; icon: string; vi: { t: string; intro: string }; en: { t: string; intro: string }; features: Feature[] }

